function ProductList({ items }) {
  const [filteredItems, setFilteredItems] = useState([]);

  // ❌ Anti-pattern
  useEffect(() => {
    setFilteredItems(items.filter(i => i.active));
  }, [items]);

  return <ul>{filteredItems.map(i => <li key={i.id}>{i.name}</li>)}</ul>;
}

